#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> datos{2, 8, 3, 3};
    int total = 0;
    for (int valor : datos) { total += valor; }
    std::cout << "N=" << datos.size() << " Total=" << total << "\n";
    if (datos.empty()) {
        std::cout << "Sin sesiones\n";
    } else {
        int menor = datos.at(0);
        int mayor = datos.at(0);
        for (int valor : datos) {
            if (valor < menor) { menor = valor; }
            if (valor > mayor) { mayor = valor; }
        }
        double media = static_cast<double>(total) / static_cast<double>(datos.size());
        auto ordenados = datos;
        std::sort(ordenados.begin(), ordenados.end());
        auto centro = ordenados.size() / 2;
        double mediana = 0.0;
        if (ordenados.size() % 2 != 0) {
            mediana = ordenados.at(centro);
        } else {
            mediana = (static_cast<double>(ordenados.at(centro - 1)) + ordenados.at(centro)) / 2.0;
        }
        std::cout << "Min=" << menor << " Max=" << mayor << " Media=" << media << " Mediana=" << mediana << "\n";
    }
    std::cout << "Orden:";
    for (int valor : datos) { std::cout << valor << ";"; }
    return 0;
}

